(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["mk"] = {"ui":{"skip":"Прескокни до содржината","back":"← Назад кон AI-gile","lang.button":"Јазик: {name}","lang.dialog":"Избери јазик","lang.search":"Пребарај јазици","lang.none":"Нема јазик што одговара","lang.notYet":"{name} сè уште не е преведен","theme.aria":"Префрли меѓу светла и темна тема","theme.toLight":"Префрли на светла тема","theme.toDark":"Префрли на темна тема","words.underline":"Подвлечи ги овие зборови на страницата","words.underlineHelp":"Застани со глувчето врз збор подвлечен со точки или допри го за да видиш што значи.","index.title":"AI-gile: твојот AI тим за развој, на една табла","index.description":"AI-gile е канбан табла за AI тимови што пишуваат код. Тие работат додека спиеш; ти останува една кратка купчинка: што да одлучиш, што да тестираш и што да прифатиш.","hero.logoAlt":"Икона на таблата AI-gile","hero.h1.html":"Твојот AI тим за развој, на една&nbsp;табла.","hero.alpha":"🐣 Затворена пред-алфа","hero.alphaTitle":"Рано и недовршено: фала што пробуваш!","hero.lede":"Градат додека спиеш. Се будиш со една кратка купчинка: неколку прашања, неколку работи за тестирање, еден-два виолетови дијаманти. Кликни, прифати и назад кон кафето.","dl.windows":"Апликација за Windows","dl.browser":"Пушти ја во прелистувач","dl.soon":"Наскоро","dl.notify":"🔔 Јави ми кога ќе се отвори","dl.notifySmall":"Алфа или бета","hero.secondary":"Agile, но тимот никогаш не бара кафе на стоење. (Stand-up сепак имаат.)","pitch.h2":"AI-gile со онолку зборови колку што сакаш","pitch.lede":"Избери должина, од еден збор до 144. Секоја должина е посебен опис, напишан токму за таа големина. Влечи го лизгачот или користи ги стрелките.","pitch.rangeLabel":"Должина во зборови","pitch.dice":"🎲 друга верзија","pitch.words.one":"{n} збор","pitch.words.other":"{n} зборови","pitch.letters.one":"{n} буква","pitch.letters.other":"{n} букви","pitch.chars.one":"{n} знак","pitch.chars.other":"{n} знаци","count.line.html.one":"{n} картичка на таблата во моментов","count.line.html.other":"{n} картички на таблата во моментов","features.aria":"Што прави","f.pile.h":"Една купчинка за тебе","f.pile.html":"<b>За тебе</b> го содржи сè што чека тебе, од сите проекти: прашања, работи за тестирање, задачи што може да ги направи само човек. Твојата редица кажува што е следно и колку трае.","f.sleep.h":"Тимови што работат додека спиеш","f.sleep.p":"Секој проект има лидер и тим од AI агенти. Коментирај на картичка и тимот се буди, ја завршува работата и ти ја враќа со чекори што ги следи и уморен човек.","f.tester.h":"Прво проверува AI тестер","f.tester.p":"Пред да стигне нешто до тебе, тестерот ги следи чекорите во копија на апликацијата и покажува што видел, со снимка од екранот. Прелистај ги поминатите и прифати со еден клик.","f.proof.h":"Докази, а не ветувања","f.proof.p":"Секое предавање покажува што се променило: датотеките, разликите, снимките од екранот. Не мора да ја отвораш секоја апликација за да видиш дали е готово.","f.chat.h":"Разговарај со твоите лидери","f.chat.p":"Лента во стил на Discord: една икона по проект, виолетови дијаманти за она што те бара тебе. Испрати идеја до лидерот; тој ја претвора во картички и план, со копче ✅ Тргнуваме.","f.tidy.h":"Сама се средува","f.tidy.p":"Сродните картички се спојуваат во една, збунетите наслови се поправаат, а проверката на токени го одржува кодот скромен. Помалку нешта меѓу кои се префрлаш, помалку за размислување.","f.private.h":"Твоја, на твојот компјутер","f.private.li1":"Таблата работи на твојот сопствен компјутер и одговара само на тебе.","f.private.li2":"Приватните пораки меѓу луѓе се шифрирани од крај до крај.","f.private.li3":"Без сметки, без следачи, без колачиња.","f.lang.h":"На твојот јазик","f.lang.p":"Над 120 јазици, од холандски, велшки и јапонски до гусарски, Јода и клингонски, со брзо враќање на англиски за програмерските зборови.","tl.aria":"Временска лента од првиот разговор до патоказот","tl.h2":"Од првиот разговор до она што следува","tl.lede":"Вистински датуми и часови, во твојата временска зона. По денес е план, без ветени датуми.","tl.today":"Денес","tl.planned":"планирано","tl.cards.one":"{n} картичка","tl.cards.other":"{n} картички","join.h2":"Придружи се","join.lede":"AI-gile го гради еден мал човек и голем број трпеливи агенти. За сега е приватна, во затворена алфа со пријатели. Сакаш да пробаш кога ќе се отвори?","join.btn":"Пријави интерес","join.small":"Ќе ти пишеме на е-пошта, ништо друго","footer.tag":"AI-gile. Без следачи, без колачиња, без кафе на стоење.","footer.licence":"Деловна лиценца","footer.status":"Статус","footer.privacy":"Што чуваме","form.sending":"Се испраќа…","form.failed":"Не успеа: обиди се повторно подоцна.","form.offline":"Не можевме да стигнеме до AI-gile: обиди се повторно подоцна.","form.keep":"Ова го користиме само за да ти одговориме, а потоа го бришеме. Без следачи, без колачиња.","form.keepLink":"Што чуваме","interest.title":"AI-gile: јави ми кога ќе се отвори алфата","interest.description":"Остави е-пошта за да дознаеш кога ќе се отвори затворената алфа или бета на AI-gile.","interest.h1":"🔔 Јави ми кога ќе се отвори","interest.lede":"AI-gile е во затворена пред-алфа. Остави е-пошта и ќе ти пишеме еднаш, кога ќе има место за тебе.","interest.email":"Твојата е-пошта","interest.which":"Кое тестирање?","interest.alpha":"Затворена алфа: рано, грубо, многу промени","interest.beta":"Бета: поцврста, подоцна","interest.both":"Кое и да е, она што ќе дојде прво","interest.submit":"Запиши ме на списокот","interest.thanks":"Фала! Си на списокот.","licence.title":"AI-gile: деловна лиценца","licence.description":"Ја користиш AI-gile во твојата фирма? Побарај бесплатна деловна лиценца.","licence.h1":"📜 Деловна лиценца","licence.lede":"Ја користиш AI-gile на работа? Кажи ни кој си и што работиш. Ако носи некаква корист, лиценцата е бесплатна.","licence.company":"Фирма","licence.website":"Веб-страница","licence.what":"Што работиш","licence.how":"Како му помага на светот","licence.email":"Е-пошта","licence.submit":"Аплицирај","licence.thanks":"Фала! Ќе одговориме по е-пошта.","status.title":"Статус на AI-gile","status.h1":"Статус на AI-gile","status.quiet":"Сè е мирно","status.intro":"Дали AI-gile работи во моментов? Оваа страница ги проверува веб-страницата, споделувањето табли, повиците и преземањето на секои 5 минути.","status.up":"Работи (одговори за {ms} ms)","status.slow":"Не одговори на последната проверка, се обидувам повторно","status.down":"Не работи: не одговори на последните две проверки","status.svc.web":"Веб-страница","status.svc.web.offers":"Оваа страница: што е AI-gile и формуларот за интерес","status.svc.boards":"Споделување табли","status.svc.boards.offers":"Јавни табли, пораки меѓу пријатели и покани","status.svc.calls":"Повици","status.svc.calls.offers":"Глас, видео и споделување екран во AI-gile","status.svc.download":"Преземање","status.svc.download.offers":"Инсталерот за Windows и линковите за покани","status.checking":"Проверувам…","status.offline":"Моментално не можам да стигнам до услугата за статус (се обидувам повторно)","status.updated":"ажурирано {ago}","status.justNow":"токму сега","status.min":"пред {n} мин","status.hours":"пред {n} ч","status.days":"пред {n} д","privacy.title":"AI-gile: што чуваме","privacy.h1":"Што чуваме","privacy.lede":"Накратко: само она што ни го праќаш, и не задолго.","privacy.only":"Само она што ни го праќаш: она што ќе го напишеш во формулар, како твојата е-пошта. Ништо друго за тебе.","privacy.sealed":"Се запечатува за нашиот сервер да не може да го прочита: во твојот прелистувач, пред да тргне (кај постар прелистувач, во мигот кога ќе пристигне). Само нашата табла може да го отвори.","privacy.server":"Се брише од серверот штом стигне до нашата табла. Сè што таму ќе остане и по 30 дена, сепак се брише.","privacy.board":"На нашата табла го чуваме само додека не ти одговориме, а потоа го бришеме и таму.","privacy.none":"Без следачи, без колачиња, без аналитика.","privacy.local":"Твојот јазик и изборот на светла или темна тема остануваат во твојот прелистувач. Никогаш не ни се испраќаат.","privacy.ask":"Сакаш да се избрише порано? Одговори на нашата е-пошта и кажи ни.","live.h2":"Гледајте како се гради, во живо","live.caption":"Секоја картичка е скриена: ја гледате формата на работата, не зборовите.","live.watching.one":"во живо: {n} гледа","live.watching.other":"во живо: {n} гледаат","live.last.now":"Последната картичка е преместена токму сега","live.last.min.one":"Последната картичка е преместена пред {n} мин.","live.last.min.other":"Последната картичка е преместена пред {n} мин.","live.last.hour.one":"Последната картичка е преместена пред {n} ч.","live.last.hour.other":"Последната картичка е преместена пред {n} ч.","live.last.day.one":"Последната картичка е преместена пред {n} д.","live.last.day.other":"Последната картичка е преместена пред {n} д.","live.offline":"Таблата во живо малку се одмора. Навратете наскоро.","live.cols":"Backlog|За работа|Во тек|Тимот проверува|За твое тестирање|За тимот|Готово"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делегирано."]},{"n":2,"texts":["Роботски канбан.","Агенти, организирани.","Идеи, изградени."]},{"n":3,"texts":["Канбан за роботи.","Идеите стануваат функции.","Бесплатен агентски канбан."]},{"n":5,"texts":["Канбан табла управувана од агенти.","Ти пишуваш картички. Агентите градат.","Бесплатно, локално, тестирано, малку смешно."]},{"n":8,"texts":["Бесплатна канбан табла каде работат AI агенти.","Напиши идеја. Агентите ја градат. Ти прифаќаш.","Agile за еден човек и многу трпеливи роботи."]},{"n":13,"texts":["Канбан табла на твојот компјутер, каде AI агентите ги земаат картичките една по една.","Напиши идеја. Тим од агенти ја гради. Тестер ја проверува и покажува што видел.","Без сметки, без следачи: табла, неколку роботи и ти, кој одлучуваш за сè."]},{"n":21,"texts":["AI-gile е канбан табла за работа со AI агенти што пишуваат код. Тие ги земаат картичките, а ти ги тестираш и прифаќаш.","Секој проект има свој лидер и тим од AI агенти. Коментирај на која било картичка и тимот веднаш се зафаќа со работа.","Бесплатна лична табла со задачи што работи на твојот компјутер. Работниците се роботи. Оној што вели „да“ си ти."]},{"n":34,"texts":["Ги ставаш идеите на таблата. Тим од AI агенти ги претвора во функции што работат, ги тестира и ти ги враќа со чекори за пробање. Ништо не е готово додека не кажеш ти.","AI-gile е домашна канбан табла што ја изгради Rich, најмногу со помош на агентите со кои сега управува. Бесплатна е, работи на твојот компјутер и се дели со пријатели, не се продава.","Замисли обична канбан табла со колони од Backlog до Готово, само што картичките ги земаат AI агенти. Известуваат за напредокот, прашуваат кога ќе се заглават и секогаш чекаат твое одобрение."]},{"n":55,"texts":["AI-gile е канбан табла каде тимот е составен од AI агенти. Секој проект има лидер што ја планира работата и помагачи што ја градат. Кога функцијата е готова, AI тестер ја испробува и прави снимка од екранот, па стигнува во твојата купчинка. Прифати ја или коментирај, и тие ја доработуваат.","Започна како начин еден човек да следи многу AI сесии за пишување код одеднаш, а израсна во вистинска табла. Работи на твојот компјутер, не бара сметка и нема следачи. Бесплатна е за пријатели и за секој љубопитен. Исто така е недовршена, па очекувај груби рабови и по некое изненадување.","Еве ја искрената верзија. Идеите сè уште мораш да ги измислиш ти, а резултатите сè уште мораш да ги провериш. AI-gile го прави сето она помеѓу: ги држи картичките во ред, го буди вистинскиот агент кога ќе коментираш, покажува што точно се променило и сè го собира во една кратка купчинка за тебе."]},{"n":89,"texts":["AI-gile е бесплатна канбан табла што ја пушташ на твојот компјутер. Наместо луѓе, секој проект има тим од AI агенти: лидер што ги претвора твоите идеи во картички и план, и помагачи што ги земаат картичките по приоритет. Кога нешто е изградено, AI тестер ги следи чекорите за тестирање и ти покажува што видел. Потоа чека во една купчинка наречена За тебе. Ти ја прифаќаш или коментираш, а тимот пробува повторно. Ништо не стигнува до Готово без тебе.","Неколку работи што можеби не ги очекуваш. Ноќна стража ја одржува колоната За работа полна додека спиеш, избирајќи картички што не бараат одговор од тебе. Бројачот на токени покажува колку агентите потрошиле денес и оваа недела, а режимот Без токени им кажува да престанат да трошат. Можеш да пишуваш на пријатели, а приватните пораки се шифрирани од крај до крај. Таблата зборува околу 120 јазици, меѓу кои холандски, фламански, гусарски и клингонски. Ништо од тоа не се плаќа, а никој не се обидува да ти го продаде.","AI-gile е мал, личен проект, а не компанија. Rich сакаше да внимава на повеќе AI проекти за пишување код без да ја отвора секоја апликација, па тој и агентите изградија табла за тоа, а потоа со таблата го изградија остатокот. Во затворена пред-алфа е, што значи дека работи, повеќе-помалку, за неколку пријатели. Нема страница со цени, нема билтен и нема план за раст. Ако ти звучи корисно, можеш да побараш да пробаш кога ќе се отвори малку повеќе."]},{"n":144,"texts":["AI-gile е канбан табла за еден човек и многу AI агенти. Работи на твојот сопствен компјутер и е сосема бесплатна. Додаваш проекти, а секој проект добива лидер и мал тим. Разговараш со лидерот, малку како на Discord, и опишуваш идеја; лидерот ја претвора во картички и план, па чека да притиснеш Тргнуваме. Тимот ги работи картичките по приоритет, преку едноставна командна линија направена за јазични модели. Пред нешто да ти се врати, AI тестер ги следи чекорите во копија на апликацијата и приложува снимка од екранот. Завршената работа стигнува во твојата купчинка со променетите датотеки и разликите. Ја прифаќаш или оставаш коментар, а тимот се буди и пробува повторно. Таблата и сама се чисти: сродните картички се спојуваат. Картичка во Готово може да префрли само ти. Никој друг, ни најдобриот агент.","Грубо, ова е еден ден со AI-gile. Навечер оставаш неколку коментари: ова копче е на погрешно место, таа листа треба да се подреди, може ли темен режим. Одиш да спиеш. Агентите ги читаат коментарите, ги прават промените, ги тестираат и ти ги враќаат. Ако За работа остане празно, ноќната стража го полни од backlog со картички што не бараат одговор од тебе. Наутро има една кратка купчинка: неколку прашања и неколку работи за пробање, секоја со чекори што ги следи и поспан човек и со снимка како работи. Кликаш, ги прифаќаш добрите и ги враќаш другите. Ако нешто не ти е јасно, само коментираш и пак стигнува до тимот. Бројачот на токени покажува колку сè потрошило, а режимот Без токени е за скромни недели. Потоа појадуваш, а во тоа агентите сè уште не можат да помогнат.","Најпрво, што AI-gile не е. Не е стартап, не се продава и никој не ги собира твоите податоци. Тоа е бесплатна табла што работи на твојот компјутер, без сметки, без следачи и без колачиња. Што е: едно уредно место за да ги видиш сите AI проекти одеднаш, со тим од агенти што ги работи картичките и ти што одлучуваш. Има и ноќна стража што ги подготвува картичките додека спиеш. Ги спојува сродните картички, ги поправа збунетите наслови и внимава колку скромен останува кодот. Зборува околу 120 јазици, од холандски и фламански до гусарски и клингонски. Пријателите можат да си праќаат пораки, приватно и шифрирано. Го изградија Rich и голем број трпеливи агенти, најмногу користејќи ја самата табла. Во затворена пред-алфа е, па на места е груба. Ако ти звучи забавно, прашај љубезно и можеби ќе влезеш рано."]}],"quips":{"1":"Еден збор. Храбро. Можеби премногу храбро.","3":"Три збора. Веќе поискрено од повеќето страници за производи.","8":"Осум зборови. Сè уште пократко од еден stand-up.","21":"Должините се story points, патем. Се разбира.","55":"Педесет и пет зборови. Додека го читаше ова, завршени се две картички.","144":"Ова е долгата. Нема 233. Агентите отидоа да спијат."}},"timeline":{"first-idea.name":"Првата идеја","first-idea.line":"Самиот прв разговор, пред да постои и еден ред код.","first-board.name":"Првата табла","first-board.line":"Табла што ја следи сопствената изградба: картички, колони, влечење, проекти.","team-roles.name":"Тим и улоги","team-roles.line":"Профили на агенти, шаблони за тимови, простори и кој што прави.","install.name":"Инсталација и изданија","install.line":"Зип што пријател може да го инсталира, самоажурирање, канали и враќање назад.","usage-saver.name":"Штедач на потрошувачка","usage-saver.line":"Мерење колку чинат извршувањата, скромен код, чување на твојот лимит.","friends.name":"Пријатели и споделување","friends.line":"Приватни пораки, шифриран релеј, покани, улоги и споделени проекти.","languages.name":"Јазици","languages.line":"Секој текст на екран во јазична датотека, прво холандски и фламански.","ai-tester.name":"AI тестер","ai-tester.line":"Тестер ја проверува секоја предавање прво и покажува што видел.","website.name":"Веб-страницата","website.line":"aigile.lol, најавата и оваа временска лента.","streaming.name":"Разговор и стриминг","streaming.line":"Discord, Twitch, OBS, режим за стримери, GIF-ови и емоџија.","no-ai.name":"Издание без AI","no-ai.line":"Табла за луѓе што пишуваат код без AI, и јавни табли.","night-watch.name":"Ноќна стража","night-watch.line":"Чувар и Scrum Master ги држат тимовите на задача додека спиеш.","p-more.name":"Сè друго","p-more.line":"Помали идеи што сè уште чекаат ред.","p-android.name":"Телефон и Android","p-android.line":"Стигни до таблата од телефон, па изворна Android апликација.","p-release.name":"Алфа и потоа","p-release.line":"Затворена алфа, живата страница, па бета.","p-languages.name":"Повеќе јазици","p-languages.line":"Над сто јазици и режим на потопување за ученици.","p-engines.name":"Повеќе AI мотори","p-engines.line":"Избери Claude, Codex или Gemini за секој агент.","p-pro.name":"Професионална пракса","p-pro.line":"Ознаки за ризик, порти за спојување, картички за инциденти и заштитни огради.","p-self.name":"Грижа за тебе","p-self.line":"Режим за уморни, потсетници за грижа за себе и 4:20.","p-servers.name":"Сервери и раст","p-servers.line":"Глобални поставки за сервери, улоги и планирање за раст.","p-livestream.name":"Додатоци за стриминг","p-livestream.line":"Twitch разговор, сопствени емоџија и јавен преглед во живо."},"words":{"button":"📖 Програмерски зборови","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Пребарај збор…","none":"Ниеден збор не одговара.","close":"Затвори","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Репо","text":"Папката на проектот со код и целата историја на комити, обично чувана и на GitHub.","also":["репозиториум","repository"]},{"id":"branch","g":"build","word":"Бранч","text":"Посебна линија на работа во кодот, за да се прават промени без да се допира главната верзија.","also":["бранчови","branches"]},{"id":"commit","g":"build","word":"Комит","text":"Зачуван снимок на кодот, со кратка белешка што се променило. Секогаш можеш да се вратиш на него.","also":["комити","commits"]},{"id":"push","g":"build","word":"Push","text":"Испраќање на зачуваните снимки (комити) од овој компјутер до GitHub, за да бидат резервирани и споделени."},{"id":"merge","g":"build","word":"Merge","text":"Спојување на промените од бранч назад во главната верзија."},{"id":"pr","g":"build","word":"Pull request","text":"Барање промените од бранч да се проверат и да се спојат во главната верзија.","also":["PR"]},{"id":"refactor","g":"build","word":"Рефакторирање","text":"Средување на кодот без менување на она што го прави: помали датотеки, појасни имиња, помалку повторување."},{"id":"bug","g":"build","word":"Баг","text":"Нешто што не работи како што треба.","also":["багови","bugs"]},{"id":"test","g":"build","word":"Тест","text":"Испробување на завршена работа за да се провери дали го прави тоа што се бараше, пред да ја прифатиш.","also":["тестови","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Деплој","text":"Пуштање на нова верзија во живо, на пример на сервер каде што ја користат луѓето."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Идеи и работа што сè уште не се испланирани. Ништо од тоа не се работи додека не се премести во За работа."},{"id":"sprint","g":"team","word":"Спринт","text":"Кус период на работа (често една или две недели) со договорен збир картички за завршување.","also":["спринтови","sprints"]},{"id":"standup","g":"team","word":"Стенд-ап","text":"Брза проверка: што направил секој член на тимот, што прави следно и што го запира.","also":["стендап","стенд-апови","standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Табла со колони (За работа, Во тек, Готово) каде картичките се движат од лево на десно додека се работи."},{"id":"wip","g":"team","word":"WIP лимит","text":"Работа во тек: најмногу картички што треба да ги држи една колона, за тимот да ги завршува работите пред да почне нови.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Агент","text":"AI што работи сам на задача: го чита кодот, прави промени, извршува проверки и известува.","also":["агенти","agents"]},{"id":"token","g":"team","word":"Токен","text":"Единицата во која се брои користењето на AI: приближно неколку букви прочитан или напишан текст. Помалку токени, повеќе ти останува од планот.","also":["токени","tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Мала команда што се извршува сама во одредено време, на пр. кога почнува AI сесија, за тимот да ги слушне твоите коментари.","also":["hooks","хукови"]}]}};
